14	/// 保证 `SqliteDb` 在内存中与 C `struct sqlite3` 的字段顺序/大小一致。
15	/// 当前 P0 阶段为最小布局;随 Pager/Schema 接入会补字段。
16	#[repr(C)]
17	pub struct SqliteDb {
18	    /// 已分配的 schema 数组(后续 P3 阶段补)。当前为 null。
19	    pub a_db: *mut SchemaEntry,
20	    /// schema 数量。
21	    pub n_db: i32,
22	    /// malloc 失败标志(对齐 C 端 `db->mallocFailed`)。
23	    pub malloc_failed: AtomicBool,
24	    /// 活跃语句数(防止在 finalize 中误关)。
