/// `sqlite3_free` — 释放。NULL 是 no-op。
///
/// C 契约(`malloc.c:391-404`):`p==NULL` 直接 return。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_free(p: *mut c_void) {
    // SAFETY: thin wrapper,所有 unsafe 在内部 API。
    unsafe { Malloc::free(p as *mut u8) }
}

