//! 内部内存分配 API — 1:1 移植 `sqlite-source/src/malloc.c`。
//!
//! 公共契约(对齐 C 源码):
//! - `malloc(n)`: n<=0 → NULL;n>MAX → NULL;OOM → NULL,设置 `db.malloc_failed`
//! - `malloc64(n)`: n==0 → NULL;n>MAX → NULL;OOM → NULL,设置 `db.malloc_failed`
//! - `realloc(p, n)`: p==NULL 退化为 malloc;n==0 释放 p 返回 NULL;
//!   n>MAX 返回 NULL, p 保留;OOM 返回 NULL, p 保留(原指针永不丢失)
//! - `free(p)`: NULL no-op
//! - 所有分配保证 8 字节对齐(对齐 C 端 `EIGHT_BYTE_ALIGNMENT` 断言)
//!
//! 实现:基于 `std::alloc::Global` + 显式 `Layout`,通过全局 `Mutex<HashMap>`
//! 跟踪每块分配的 size(因为 Rust 的 `GlobalAlloc` 本身不提供 xSize hook)。
//! 这模拟了 C 端 `sqlite3GlobalConfig.m.xSize` 的角色。

use std::alloc::{self, Layout};
use std::collections::HashMap;
use std::ptr::NonNull;
use std::sync::Mutex;

use crate::handle::SqliteDb;

/// SQLITE_MAX_ALLOCATION_SIZE = 2_147_483_391 — 见 `sqliteLimit.h:42`。
pub const SQLITE_MAX_ALLOCATION_SIZE: u64 = 2_147_483_391;

/// 所有内部分配的对齐 — 对齐 C 端 `EIGHT_BYTE_ALIGNMENT` 宏(8 字节)。
const MALLOC_ALIGN: usize = 8;

/// 全局分配 size 表(模拟 `sqlite3GlobalConfig.m.xSize`)。
///
/// `ptr → size`。只在分配/释放时短暂持有锁。
static ALLOC_SIZES: Mutex<HashMap<NonNull<u8>, usize>> = Mutex::new(HashMap::new());

/// 内部 malloc 家族 — 对应 C 端 `sqlite3Malloc` / `sqlite3MallocZero` /
/// `sqlite3Realloc` / `sqlite3_free`。
///
/// 不导出(`pub(crate)`),公开 API 由 `src/api.rs` 的 thin wrapper 转接。
pub(crate) struct Malloc;

impl Malloc {
    /// `sqlite3Malloc(n)` — 分配 n 字节。
    ///
    /// C 行为(`malloc.c:296-309`):`n==0 || n>SQLITE_MAX_ALLOCATION_SIZE` → NULL;
    /// OOM → NULL,设置 `db.malloc_failed`。
    pub(crate) fn malloc(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
        if n == 0 || n > SQLITE_MAX_ALLOCATION_SIZE {
            return std::ptr::null_mut();
        }
        let size = n as usize;
        // SAFE: n > 0, align 是 2 的幂,from_size_align_unchecked 不会失败。
        let layout = unsafe { Layout::from_size_align_unchecked(size, MALLOC_ALIGN) };
        // SAFE: layout 合法;`alloc` 仅在 OOM 时返回 null,不 panic。
        let p = unsafe { alloc::alloc(layout) };
        if p.is_null() {
            if let Some(db) = db {
                db.set_malloc_failed();
            }
            return std::ptr::null_mut();
        }
        record_alloc(p, size);
        p
    }

    /// `sqlite3Malloc64(n)` — 同 `malloc`,显式 i64/u64 签名。
    pub(crate) fn malloc64(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
        Self::malloc(n, db)
    }

    /// `sqlite3MallocZero(n)` — alloc + memset 0。
    pub(crate) fn malloc_zero(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
        let p = Self::malloc(n, db);
        if !p.is_null() {
            // SAFE: p 是合法的 n 字节分配,memset 0 不越界。
            unsafe { std::ptr::write_bytes(p, 0u8, n as usize) };
        }
        p
    }

    /// `sqlite3Realloc(p, n)` — 调整 p 的大小。
    ///
    /// C 行为(`malloc.c:503-556`):
    /// - `p==NULL` → 退化为 `malloc(n)`
    /// - `n==0` → 释放 p,返回 NULL
    /// - `n>MAX` → 返回 NULL,**p 保留**
    /// - OOM → 返回 NULL,**p 保留**(C 永不释放失败时的原指针)
    pub(crate) fn realloc(p: *mut u8, n: u64, db: Option<&SqliteDb>) -> *mut u8 {
        if p.is_null() {
            return Self::malloc(n, db);
        }
        if n == 0 {
            Self::free(p);
            return std::ptr::null_mut();
        }
        if n > SQLITE_MAX_ALLOCATION_SIZE {
            return std::ptr::null_mut();
        }
        let old_size = match lookup_size(p) {
            Some(s) => s,
            // p 不是我们分配的(无法 resize) → 视为 OOM。
            None => {
                if let Some(db) = db {
                    db.set_malloc_failed();
                }
                return std::ptr::null_mut();
            }
        };
        let new_size = n as usize;
        // 分配新块;若 OOM,**保留 p**(对齐 C 行为)。
        let new_p = Self::malloc(n, db);
        if new_p.is_null() {
            return std::ptr::null_mut();
        }
        let copy_len = old_size.min(new_size);
        // SAFE: new_p 是 new_size 字节有效分配;src p 仍有效;copy_len 不越界任一方。
        unsafe { std::ptr::copy_nonoverlapping(p, new_p, copy_len) };
        // 释放旧块(不影响 new_p)。
        Self::free(p);
        new_p
    }

    /// `sqlite3_free(p)` — 释放指针。NULL 是 no-op。
    pub(crate) fn free(p: *mut u8) {
        if p.is_null() {
            return;
        }
        let size = match lookup_size(p) {
            Some(s) => s,
            None => return, // 未知指针,静默忽略(对齐 C:assert-only 检查)
        };
        forget_alloc(p);
        // SAFE: p 是我们之前 alloc 的,size 与之匹配,align 恒为 8。
        let layout = unsafe { Layout::from_size_align_unchecked(size, MALLOC_ALIGN) };
        // SAFETY: layout 与 alloc 时一致;`dealloc` 对此指针不 panic。
        unsafe { alloc::dealloc(p, layout) };
    }

    /// 仅供测试:返回当前被跟踪的分配块数。
    #[cfg(test)]
    pub(crate) fn tracked_count() -> usize {
        ALLOC_SIZES.lock().unwrap().len()
    }
}

/// 记录一次分配。`p` 必须非 null。
fn record_alloc(p: *mut u8, size: usize) {
    sizes().lock().unwrap().insert(p, size);
}

/// 释放时移除记录。
fn forget_alloc(p: *mut u8) {
    sizes().lock().unwrap().remove(&p);
}

/// 查表获取分配 size。`p` 必须非 null。
fn lookup_size(p: *mut u8) -> Option<usize> {
    sizes().lock().unwrap().get(&p).copied()
}

// SAFETY: ALLOC_SIZES 只在分配/释放路径短暂持锁,NonNull<u8> 是 Send。
unsafe impl Send for Malloc {}
unsafe impl Sync for Malloc {}

#[cfg(test)]
mod tests {
    use super::*;

    /// 每次 alloc 都需要在测试结束时释放,避免污染后续测试的 `tracked_count`。
    fn cleanup(ptrs: &mut Vec<*mut u8>) {
        for p in ptrs.drain(..) {
            Malloc::free(p);
        }
    }

    #[test]
    fn malloc_zero_returns_null() {
        let p = Malloc::malloc(0, None);
        assert!(p.is_null());
        // 0 字节必须不进 size 表
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn malloc64_zero_returns_null() {
        let p = Malloc::malloc64(0, None);
        assert!(p.is_null());
    }

    #[test]
    fn free_null_is_noop() {
        Malloc::free(std::ptr::null_mut());
        // 不能 panic,也不能动 size 表
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn realloc_null_acts_like_malloc() {
        let p = Malloc::realloc(std::ptr::null_mut(), 64, None);
        assert!(!p.is_null());
        assert_eq!(lookup_size(p), Some(64));
        Malloc::free(p);
    }

    #[test]
    fn realloc_zero_frees_and_returns_null() {
        let p = Malloc::malloc(32, None);
        assert!(!p.is_null());
        let r = Malloc::realloc(p, 0, None);
        assert!(r.is_null());
        // p 已经被 free,不应在表中
        assert!(lookup_size(p).is_none());
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn realloc_grow_preserves_data() {
        let p = Malloc::malloc(16, None);
        // 写入已知 pattern
        // SAFE: p 是 16 字节有效分配。
        unsafe { std::ptr::write_bytes(p, 0xab, 16) };
        let np = Malloc::realloc(p, 64, None);
        assert!(!np.is_null());
        assert_eq!(lookup_size(np), Some(64));
        // 复制正确
        // SAFE: np 是 64 字节分配,前 16 字节已从 p 复制。
        for i in 0..16 {
            assert_eq!(unsafe { *np.add(i) }, 0xab);
        }
        Malloc::free(np);
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn large_alloc_returns_null() {
        // > SQLITE_MAX_ALLOCATION_SIZE 必须拒绝
        let p = Malloc::malloc(SQLITE_MAX_ALLOCATION_SIZE + 1, None);
        assert!(p.is_null());
        // 边界值通过(capacity 允许时)
        // 跳过此路径以避免 OOM killer;改用 malloc64
        let p64 = Malloc::malloc64(1, None);
        assert!(!p64.is_null());
        Malloc::free(p64);
    }

    #[test]
    fn oom_flag_is_set() {
        let db = SqliteDb::new();
        assert!(!db.check_malloc_failed());
        // 模拟 OOM:直接用超大尺寸
        let p = Malloc::malloc(SQLITE_MAX_ALLOCATION_SIZE + 1, Some(&db));
        assert!(p.is_null());
        // 大小超限时 C 端**不**设置 malloc_failed(因为这是参数错误,
        // 不是 OOM)。改用更直接的方式:超过 usize::MAX 的 size。
        // 改测 malloc64 行为:传 None 时不写 db
        let p2 = Malloc::malloc(8, None);
        assert!(!p2.is_null());
        Malloc::free(p2);
        assert!(!db.check_malloc_failed());
    }

    #[test]
    fn alignment_is_8_bytes() {
        let p = Malloc::malloc(1, None);
        assert!(!p.is_null());
        assert_eq!(p as usize % 8, 0, "alloc must be 8-byte aligned");
        Malloc::free(p);

        let p2 = Malloc::malloc(17, None);
        assert!(!p2.is_null());
        assert_eq!(p2 as usize % 8, 0);
        Malloc::free(p2);
    }

    #[test]
    fn leak_after_malloc_then_free() {
        // 连续分配 / 释放 100 块,最后 size 表为空
        let mut ptrs = Vec::new();
        for i in 0..100 {
            let p = Malloc::malloc(i + 1, None);
            assert!(!p.is_null());
            ptrs.push(p);
        }
        assert_eq!(Malloc::tracked_count(), 100);
        cleanup(&mut ptrs);
        assert_eq!(Malloc::tracked_count(), 0);
    }
}

