    /// 每次 alloc 都需要在测试结束时释放,避免污染后续测试的 `tracked_count`。
    fn cleanup(ptrs: &mut Vec<*mut u8>) {
        for p in ptrs.drain(..) {
            Malloc::free(p);
        }
    }

    #[test]
    fn malloc_zero_returns_null() {
        let p = Malloc::malloc(0, None);
        assert!(p.is_null());
        // 0 字节必须不进 size 表
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn malloc64_zero_returns_null() {
        let p = Malloc::malloc64(0, None);
        assert!(p.is_null());
    }

    #[test]
    fn free_null_is_noop() {
        Malloc::free(std::ptr::null_mut());
        // 不能 panic,也不能动 size 表
        assert_eq!(Malloc::tracked_count(), 0);
    }

    #[test]
    fn realloc_null_acts_like_malloc() {
        let p = Malloc::realloc(std::ptr::null_mut(), 64, None);
        assert!(!p.is_null());
        assert_eq!(lookup_size(p), Some(64));
        Malloc::free(p);
    }

    #[test]
    fn realloc_zero_frees_and_returns_null() {
        let p = Malloc::malloc(32, None);
        assert!(!p.is_null());
        let r = Malloc::realloc(p, 0, None);
        assert!(r.is_null());
        // p 已经被 free,不应在表中
        assert!(lookup_size(p).is_none());
        assert_eq!(Malloc::tracked_count(), 0);
    }

