        let layout = unsafe { Layout::from_size_align_unchecked(size, MALLOC_ALIGN) };
        // SAFETY: layout 与 alloc 时一致;`dealloc` 对此指针不 panic。
        unsafe { alloc::dealloc(p, layout) };
    }

