    fn leak_after_malloc_then_free() {
        // 连续分配 / 释放 100 块,最后 size 表为空
        let mut ptrs = Vec::new();
        for i in 0..100 {
            let p = Malloc::malloc(i + 1, None);
            assert!(!p.is_null());
            ptrs.push(p);
        }
        assert_eq!(Malloc::tracked_count(), 100);
        cleanup(&mut ptrs);
        assert_eq!(Malloc::tracked_count(), 0);
    }
}

